                int brightness = (int) (0.2126 * ((pixel >> 16) & 0xff) +
                                        0.7152 * ((pixel >> 8) & 0xff) +
                                        0.0722 * (pixel & 0xff));
                histogram[brightness]++;
            }
        }
        return histogram;
    }

