You're facing two main issues:

1. **Grid hides the wireframe model** – The grid is drawn on top of the model because it's rendered in the same canvas context.
2. **Snap-to-grid is not working** – The `snapToGrid` function exists, but it's not being used anywhere in the code.

---

### ✅ Solution Overview

To fix both issues:

- **Render the grid in a separate transparent layer** (e.g., a second canvas or using CSS).
- **Use `snapToGrid` to align vertex positions** when the user updates vertex values or drags them.

---

### ✅ Step-by-Step Fix

#### ✅ 1. Add a second canvas for the grid

Replace this:

```html
<canvas id="main-canvas"></canvas>
```

With:

```html
<canvas id="main-canvas"></canvas>
<canvas id="grid-canvas" style="position:absolute;top:0;left:0;pointer-events:none;"></canvas>
```

Then update your JS to use both canvases:

```js
const mainCanvas = document.getElementById('main-canvas');
const mainCtx = mainCanvas.getContext('2d');
const gridCanvas = document.getElementById('grid-canvas');
const gridCtx = gridCanvas.getContext('2d');

// Set grid canvas size
function resizeGridCanvas() {
  gridCanvas.width = window.innerWidth;
  gridCanvas.height = window.innerHeight;
}
resizeGridCanvas();
window.addEventListener('resize', resizeGridCanvas);
```

#### ✅ 2. Draw grid on the grid canvas

Update your `drawGrid()` function to use `gridCtx`:

```js
function drawGrid() {
  gridCtx.clearRect(0, 0, gridCanvas.width, gridCanvas.height);
  gridCtx.strokeStyle = 'rgba(0, 0, 0, 0.2)';
  gridCtx.lineWidth = 1;

  for (let x = gridSize; x < gridCanvas.width; x += gridSize) {
    gridCtx.beginPath();
    gridCtx.moveTo(x + 0.5, 0);
    gridCtx.lineTo(x + 0.5, gridCanvas.height);
    gridCtx.stroke();
  }

  for (let y = gridSize; y < gridCanvas.height; y += gridSize) {
    gridCtx.beginPath();
    gridCtx.moveTo(0, y + 0.5);
    gridCtx.lineTo(gridCanvas.width, y + 0.5);
    gridCtx.stroke();
  }
}
```

Call `drawGrid()` in your render loop:

```js
function render() {
  mainCtx.fillStyle = '#FFF';
  mainCtx.fillRect(0, 0, mainCanvas.width, mainCanvas.height);

  // ... your 3D rendering code ...

  drawGrid(); // draw grid on top
  requestAnimationFrame(render);
}
```

#### ✅ 3. Use `snapToGrid` when updating vertex values

Update your `updateVertexValue` function:

```js
function updateVertexValue(event, indexToUpdate) {
  const newValue = parseFloat(event.target.value);
  const vertexIndex = parseInt(event.target.dataset.vertexIndex);

  if (!isNaN(newValue) && vertexIndex >= 0) {
    vertices[vertexIndex][indexToUpdate] = snapToGrid(newValue);
  }
}
```

