To achieve this in **NestJS + GraphQL + Prisma**, you need to:

1. **Filter vans** that have **at least one available variation** for the given date range.
2. **Return all variations** for those vans, **deduplicated** (i.e., unique `VanVariation` records).
3. **Include the associated van IDs** in the result.

---

### ✅ Assumptions

- `VanVariation` has a `vanId` and a `date` field.
- A variation is **available** if it is **not booked** for the given date range.
- You want to **deduplicate** `VanVariation` by its **name or type**, not by ID.

---

### ✅ Prisma Schema (simplified)

```prisma
model Van {
  id        String   @id @default(cuid())
  variations VanVariation[]
}

model VanVariation {
  id     String @id @default(cuid())
  vanId  String
  name   String
  date   DateTime
  booked Boolean @default(false)

  van Van @relation(fields: [vanId], references: [id])
}

model Booking {
  id        String   @id @default(cuid())
  vanId     String
  vanVarId  String
  fromDate  DateTime
  toDate    DateTime
}
```

---

### ✅ GraphQL Query

```graphql
query GetAvailableVans($fromDate: DateTime!, $toDate: DateTime!) {
  availableVans(fromDate: $fromDate, toDate: $toDate) {
    id
    variations {
      id
      name
      date
      vanId
    }
  }
}
```

---

### ✅ Resolver Logic (NestJS)

```ts
@Resolver()
export class VanResolver {
  constructor(private prisma: PrismaService) {}

  @Query(() => [Van])
  async availableVans(
    @Args('fromDate', { type: () => Date }) fromDate: Date,
    @Args('toDate', { type: () => Date }) toDate: Date,
  ) {
    // Step 1: Find all van variations that are NOT booked in the date range
    const bookedVariations = await this.prisma.booking.findMany({
      where: {
        OR: [
          { fromDate: { lte: toDate }, toDate: { gte: fromDate } },
        ],
      },
      select: { vanVarId: true },
    });

    const bookedVarIds = bookedVariations.map(b => b.vanVarId);

    // Step 2: Get all van variations that are NOT booked
    const availableVariations = await this.prisma.vanVariation.findMany({
      where: {
        id: { notIn: bookedVarIds },
      },
      include: {
        van: true,
      },
    });

    // Step 3: Deduplicate by variation name
    const seen = new Set<string>();
    const uniqueVariations: VanVariation[] = [];

    for (const var of availableVariations) {
      if (!seen.has(var.name)) {
        seen.add(var.name);
        uniqueVariations.push(var);
      }
    }

    // Step 4: Group by van
    const vanMap = new Map<string, Van>();
    for (const var of uniqueVariations) {
      if (!vanMap.has(var.vanId)) {
        vanMap.set(var.vanId, {
          id: var.vanId,
          variations: [],
        });
      }
      vanMap.get(var.vanId)!.variations.push(var);
    }

    return Array.from(vanMap.values());
  }
}
```

