### 🧠 Contract: `BEP20Token`
```solidity
contract BEP20Token is BEP20, BEP20Pausable, Ownable, Initializable, UUPSUpgradeable, ReentrancyGuard {
    uint256 public constant FEE_PERCENT = 3; // 3% fee
    address public liquidityPool;
    address public feeRecipient;

    mapping(address => bool) public canSell;

    event LiquidityPoolSet(address indexed pool);
    event FeeRecipientSet(address indexed recipient);
    event Minted(address indexed to, uint256 amount, uint256 paid);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string memory name,
        string memory symbol,
        uint256 initialSupply,
        address _liquidityPool,
        address _feeRecipient
    ) public initializer {
        __BEP20_init(name, symbol);
        __BEP20Pausable_init();
        __Ownable_init(_msgSender());
        __UUPSUpgradeable_init();

        _mint(address(this), initialSupply);
        _mint(msg.sender, initialSupply);

        liquidityPool = _liquidityPool;
        feeRecipient = _feeRecipient;
        canSell[msg.sender] = true;
    }

    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal override whenNotPaused {
        if (from != owner() && to != owner() && from != address(this)) {
            uint256 fee = (amount * FEE_PERCENT) / 100;
            super._transfer(from, feeRecipient, fee);
            amount -= fee;
        }
        super._transfer(from, to, amount);
    }

    function mint(address to, uint256 amount) external payable nonReentrant {
        require(msg.value > 0, "Must pay BNB");
        uint256 cost = msg.value;
        uint256 tokens = (cost * 10**decimals()) / 1e18; // 1 BNB = 1 token (adjust as needed)
        require(tokens >= amount, "Insufficient BNB");

        _mint(to, amount);
        emit Minted(to, amount, msg.value);

        (bool success, ) = payable(owner()).call{value: msg.value}("");
        require(success, "Transfer failed");
    }

    function setLiquidityPool(address _pool) external onlyOwner {
        liquidityPool = _pool;
        emit LiquidityPoolSet(_pool);
    }

    function setFeeRecipient(address _recipient) external onlyOwner {
        feeRecipient = _recipient;
        emit FeeRecipientSet(_recipient);
    }

    function setCanSell(address account, bool value) external onlyOwner {
        canSell[account] = value;
    }

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal override whenNotPaused {
        super._beforeTokenTransfer(from, to, amount);
    }

    function _authorizeUpgrade(address newImplementation)
        internal
        override
        onlyOwner
    {}

    function rescueETH(uint256 amount) external onlyOwner {
        payable(owner()).transfer(amount);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function restore() external onlyOwner {
        _unpause();
    }
}
```

